#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MyDesk v304 適用（見積明細に「単位種別(kg/立米/袋 等)」欄を追加）
使い方: dashboard.jsx と同じフォルダで  python3 apply_v304_dashboard.py"""
import gzip, base64, json, sys, os
PATH="dashboard.jsx"
if not os.path.exists(PATH):
    print("❌ dashboard.jsx が見つかりません。同じフォルダで実行してください。"); sys.exit(1)
PAIRS=json.loads('[["H4sIAIHRa2oC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1wWSZcYGxrqFpfklqbrJ+cUluklFqYnZKfnleUrWCvr6Co+bJz9uXv24ufPF2hlPO5Y+XTsBAHZRH0JSAAAA", "H4sIAIHRa2oC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1zUy1y0zNjDRLSzNL0nVLc3LLCmpLEhVslbQ11d43Dz5cfPqx82dL9bOeNqx9OnaCQC7bHY6TAAAAA=="], ["H4sIAIHRa2oC/02NbQqAMAiG79Lv6ADdRtpig6W1WRCtu6fGoj/6vB/otXgO5MY0vFBr1/U7RhZHl+mNT5EyTXEGLCtlrXxsiYvCBZIEDc2fE2hZl2k6fA4e9GtD8ydCFzkSSvBxrWlAYm8NhfGnYaEd9fYL6t0P+aB/tdMAAAA=", "H4sIAIHRa2oC/02O0Q3DMAhEd8l3lQEyRxdAtatYciB1SKWo7u7lcGL1B97dgc1niTpLmPLYoNZhuO2c1Bw01y89TFrt6f1Y4zkBdF8L8bZKwWpnT0Iy3ihbcKH7z0wYRnMt71jmSLjmQvcfwiFpEragc615ZNH2N2D607TIzni7AbzvD/vFCQfrAAAA"], ["", ""]]')
def dec(b): return gzip.decompress(base64.b64decode(b)).decode("utf-8")
raw=open(PATH,"rb").read(); had_crlf=b"\r\n" in raw
text=raw.replace(b"\r\n",b"\n").decode("utf-8")
applied=skipped=0
for eo,en in PAIRS:
    old,new=dec(eo),dec(en)
    if text.count(new)>=1: skipped+=1; continue
    c=text.count(old)
    if c==0:
        print("❌ 対象が見つかりません（現在のビルドを確認）:"); print("   "+old[:80].replace("\n"," / ")); print("   grep MYDESK_BUILD dashboard.jsx"); sys.exit(1)
    if c!=1:
        print("❌ 対象が%d箇所（1箇所想定）"%c); sys.exit(1)
    text=text.replace(old,new,1); applied+=1
out=text.replace("\n","\r\n").encode("utf-8") if had_crlf else text.encode("utf-8")
open(PATH,"wb").write(out)
print("✅ v304 適用完了 (適用 %d / スキップ %d)"%(applied,skipped))
print("   ビルド: 2026-07-27-v304-quote-unittype")
